      "analysis_type": {
        "type": "string",
        "description": "Loại phân tích cần thực hiện (ví dụ: regression, clustering)"
      },
      "output_format": {
        "type": "string",
        "description": "Định dạng đầu ra mong muốn (ví dụ: CSV, JSON, trực quan hóa)"
